"use client"

import { useEffect, useState } from "react"
import { auth } from "@/lib/firebase"
import { onAuthStateChanged } from "firebase/auth"
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/Card"
import { BadgeCheck, PlayCircle, MapPin, Clock, CheckCircle2, XCircle } from "lucide-react"

export default function DashboardPage() {
  const [bookings, setBookings] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [userName, setUserName] = useState("")

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setUserName(user.displayName || "User")
        try {
          const token = await user.getIdToken()
          const res = await fetch("http://localhost:3001/api/v1/bookings", {
            headers: {
              "Authorization": `Bearer ${token}`
            }
          })
          const json = await res.json()
          if (json.success) {
            setBookings(json.data)
          }
        } catch (err) {
          console.error("Failed to fetch bookings", err)
        } finally {
          setLoading(false)
        }
      }
    })

    return () => unsubscribe()
  }, [])

  const activeCount = bookings.filter(b => b.status !== 'COMPLETED' && b.status !== 'CANCELLED').length
  const completedCount = bookings.filter(b => b.status === 'COMPLETED').length

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'COMPLETED': return <CheckCircle2 className="w-4 h-4" />
      case 'CANCELLED': return <XCircle className="w-4 h-4 text-red-500" />
      default: return <BadgeCheck className="w-4 h-4" />
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'COMPLETED': return 'bg-green-100 text-green-800'
      case 'CANCELLED': return 'bg-red-100 text-red-800'
      case 'IN_PROGRESS': return 'bg-blue-100 text-blue-800'
      default: return 'bg-amber-100 text-amber-800'
    }
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-serif font-bold text-orange-950 mb-2">
          {loading ? "Syncing..." : `Welcome Back, ${userName}`}
        </h1>
        <p className="text-orange-900/60">Manage your bookings securely and view your ritual proofs here.</p>
      </div>

      <div className="grid md:grid-cols-3 gap-6">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-lg text-orange-900">Active Bookings</CardTitle>
          </CardHeader>
          <CardContent>
            <span className="text-3xl font-bold text-amber-600">{loading ? "..." : activeCount}</span>
          </CardContent>
        </Card>
        
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-lg text-orange-900">Rituals Completed</CardTitle>
          </CardHeader>
          <CardContent>
            <span className="text-3xl font-bold text-orange-950">{loading ? "..." : completedCount}</span>
          </CardContent>
        </Card>
      </div>

      <div className="mt-12">
        <h2 className="text-xl font-bold text-orange-950 mb-6 border-b border-orange-200 pb-2">Ongoing Ritual Itinerary</h2>
        
        {loading ? (
          <div className="py-12 text-center text-orange-900/40 animate-pulse">Retrieving your sacred records...</div>
        ) : bookings.length === 0 ? (
          <Card className="p-12 text-center text-orange-900/60 border-dashed">
            No active rituals found. Start by arranging a new ritual.
          </Card>
        ) : (
          <div className="space-y-6">
            {bookings.map((booking) => (
              <Card key={booking.id} className="border-l-4 border-l-amber-500 overflow-hidden relative transition-all hover:shadow-md">
                <div className={`absolute top-4 right-4 flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold ${getStatusColor(booking.status)}`}>
                  {getStatusIcon(booking.status)} {booking.status}
                </div>

                <CardContent className="p-6 md:p-8 flex flex-col md:flex-row gap-8 justify-between">
                  <div className="space-y-4">
                    <div>
                      <h3 className="font-serif text-2xl font-bold text-orange-950">{booking.service?.name || "Sacred Ritual"}</h3>
                      <div className="flex items-center gap-2 text-sm text-orange-900/60 mt-1">
                        <MapPin className="w-4 h-4" /> {booking.location?.name || "Varanasi"}
                      </div>
                    </div>
                    
                    <div className="grid grid-cols-2 gap-y-4 gap-x-8 text-sm">
                      <div>
                        <span className="block text-orange-900/50 mb-1">Departed Soul:</span>
                        <span className="font-semibold text-orange-950">{booking.departedName}</span>
                      </div>
                      <div>
                        <span className="block text-orange-900/50 mb-1">Gotra:</span>
                        <span className="font-semibold text-orange-950">{booking.gotra || "N/A"}</span>
                      </div>
                      <div>
                        <span className="block text-orange-900/50 mb-1 flex items-center gap-1"><Clock className="w-3 h-3"/> Scheduled Date:</span>
                        <span className="font-semibold text-orange-950">{new Date(booking.ritualDate).toLocaleDateString(undefined, { dateStyle: 'long' })}</span>
                      </div>
                      <div>
                        <span className="block text-orange-900/50 mb-1">Father's Name:</span>
                        <span className="font-semibold text-orange-950">{booking.fatherName || "N/A"}</span>
                      </div>
                    </div>
                  </div>

                  <div className="bg-orange-50 rounded-xl p-6 flex flex-col items-center justify-center min-w-[200px] border border-orange-100 text-center">
                    {booking.status === 'COMPLETED' ? (
                        <div className="flex flex-col items-center">
                            <PlayCircle className="w-10 h-10 text-amber-600 mb-2 cursor-pointer hover:scale-110 transition-transform" />
                            <p className="text-sm text-orange-950 font-bold">Watch Video Proof</p>
                        </div>
                    ) : (
                        <>
                            <PlayCircle className="w-10 h-10 text-orange-300 mb-2" />
                            <p className="text-sm text-orange-900 font-medium max-w-[150px]">
                                Video proofs will appear here once the ritual is completed.
                            </p>
                        </>
                    )}
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
